def auc(pos, neg):
    wins = 0.0
    for p in pos:
        for n in neg:
            wins += 1.0 if p > n else 0.5 if p == n else 0.0
    return wins / (len(pos) * len(neg))

print("auc:", round(auc([0.9, 0.8, 0.4], [0.7, 0.4, 0.2]), 3))
print("perfect:", auc([0.9, 0.8], [0.2, 0.1]))
print("reversed:", auc([0.1, 0.2], [0.8, 0.9]))
print("all ties:", auc([0.5, 0.5], [0.5, 0.5]))

labels = [0] * 6 + [1] * 6

def kfold(n, k):
    return [list(range(i * n // k, (i + 1) * n // k)) for i in range(k)]

def stratified(labels, k):
    folds = [[] for _ in range(k)]
    for c in sorted(set(labels)):
        idx = [i for i, l in enumerate(labels) if l == c]
        for j, i in enumerate(idx):
            folds[j % k].append(i)
    return folds

print("plain positives per test fold:", [sum(labels[i] for i in f) for f in kfold(12, 3)])
print("stratified positives per test fold:", [sum(labels[i] for i in f) for f in stratified(labels, 3)])
